# 34_crown_base.R  Height to crown base (HCB) for natural koa, by the rules of 2026-11-14_koa-height-crown-standmort_PREREG.md (section 2).
# Data: the 360 FIA koa trees with a crown base in the frame of record (AK_HCB_v103.csv), joined to the tree table for competition and site.
# Forms: HCB = HT / (1 + exp(eta)); eta built up from ln HT, DBH/HT, x = (BAL/BA) RD and ln BYI. C0 is a constant ratio of height. P7 is the
# form of the earlier builds, refitted with the covariates of the present system (PREREG section 5).
# Rule: fewest terms within 2% of the lowest held-out RMSE, installations held out. Static component; nothing else in the system uses it.
suppressMessages(library(data.table)); setwd("~/jobs/koa_final_eq_20261110"); source("scripts/utils.R"); NB <- as.integer(Sys.getenv("KOA_NBOOT", "2000"))
f <- readRDS("frames/frames.rds"); tr <- f$tr; FT <- readRDS("out/rdbyi2_fits.rds"); bs <- FT$bs; h <- fread("~/jobs/koa_v105final_20261103/frames/final/AK_HCB_v103.csv"); h[, pid := paste(Data, Install, Plot, sep = "|")]
d <- merge(h[, .(pid, Tree = as.character(Tree), Measure = INVYR, HCB)], tr[, .(pid, Data, Install, Tree = as.character(Tree), Measure, DBH, HT, BAL, BA_koa, SDI_koa, BYI, planted)], by = c("pid", "Tree", "Measure")); stopifnot(nrow(d) == 360, all(d$planted == 0))
d[, `:=`(sm = exp(bs[[1]] + bs[[2]] * log(BYI) + bs[[3]] * planted), inst = paste(Data, Install))]; d[, `:=`(x = BAL / pmax(BA_koa, 1e-6) * SDI_koa / sm, lH = log(HT), dh = DBH / HT, lb = log(BYI), cr = 1 - HCB / HT, s1 = sqrt(HT / 100), lhd = log(HT / DBH), sb = sqrt(BAL * BA_koa + 1), lba = log(BA_koa + 1), lb100 = log(BYI / 100))]; d <- merge(d, make_folds(d), by = "inst")
cat("frame: trees", nrow(d), "; plots", uniqueN(d$pid), "; installations", uniqueN(d$inst), "; folds", uniqueN(d$fold), "\nranges: DBH", round(range(d$DBH), 1), "cm; HT", round(range(d$HT), 1), "m; HCB", round(range(d$HCB), 1), "m; crown ratio", round(range(d$cr), 2), "mean", round(mean(d$cr), 3), "; x", round(range(d$x), 2), "; BYI", round(range(d$BYI)), "\n")
cat("distinct crown ratio values:", uniqueN(round(d$cr, 2)), " (", paste(head(sort(unique(round(d$cr, 2))), 12), collapse = " "), "...)\n")
TM <- list(C0 = character(0), C1 = "lH", C2 = c("lH", "dh"), C3 = c("lH", "dh", "x"), C4 = c("lH", "dh", "x", "lb"), C5 = c("lH", "x"), C6 = c("dh", "x"), P7 = c("s1", "lhd", "sb", "lba", "lb100"))   # P7: the form of the earlier builds (its eta has the opposite sign convention)
pred <- function(b, dd, tm) dd$HT / (1 + exp(as.numeric(cbind(rep(1, nrow(dd)), if (length(tm)) as.matrix(dd[, ..tm])) %*% b)))
fit <- function(dd, tm) { b <- optim(c(1, rep(0, length(tm))), function(b) sum((dd$HCB - pred(b, dd, tm))^2), method = "BFGS", control = list(maxit = 1000, reltol = 1e-12)); setNames(b$par, c("b0", tm)) }
FC <- lapply(TM, function(tm) fit(d, tm)); cat("\n(1) full fits\n"); for (nm in names(TM)) { p <- pred(FC[[nm]], d, TM[[nm]]); cat(nm, "RMSE", round(sqrt(mean((d$HCB - p)^2)), 4), " "); print(round(FC[[nm]], 4)) }
cv <- rbindlist(lapply(names(TM), function(nm) rbindlist(lapply(sort(unique(d$fold)), function(k) { b <- fit(d[fold != k], TM[[nm]]); te <- d[fold == k]; data.table(form = nm, pid = te$pid, obs = te$HCB, pred = pred(b, te, TM[[nm]]), HT = te$HT) }))))
tab <- cv[, c(metrics(obs, pred), equiv_boot(obs, pred, pid, nboot = 2000)[, .(bias_rel, slope, b1_lo, b1_hi, pass_int, pass_slope, min_region_int, min_region_slope)]), by = form]; tab[, k := sapply(TM[form], length) + 1]; tab[, r2 := cv[, 1 - sum((obs - pred)^2) / sum((obs - mean(obs))^2), by = form]$V1]
cat("\n(2) held-out installations, HCB (m)\n"); print(tab); pk <- tab[rmse <= min(rmse) * 1.02][order(k, rmse)]$form[1]; cat("rule: fewest terms within 2% of the lowest held-out RMSE ->", pk, "\n")
cat("held-out error of the chosen form on the crown ratio scale: RMSE", round(cv[form == pk, sqrt(mean(((1 - obs / HT) - (1 - pred / HT))^2))], 3), "\n")
idx <- split(seq_len(nrow(d)), d$pid); pids <- names(idx); set.seed(20261114); BO <- t(replicate(NB, { ix <- unlist(idx[sample(pids, length(pids), TRUE)], use.names = FALSE); fit(d[ix], TM[[pk]]) })); if (nrow(BO) == 1) BO <- t(BO)
cat("\n(3) plot-cluster bootstrap of", pk, "(", NB, "resamples)\n"); print(round(rbind(est = FC[[pk]], se = apply(BO, 2, sd), lo = apply(BO, 2, quantile, .025), hi = apply(BO, 2, quantile, .975)), 4))
p <- pred(FC[[pk]], d, TM[[pk]]); cat("residual SD (m):", round(sd(d$HCB - p), 3), "; observed crown ratio 5th, 50th, 95th percentile:", round(quantile(d$cr, c(.05, .5, .95)), 2), "; height to diameter ratio (m per m) 5th, 50th, 95th:", round(quantile(100 * d$HT / d$DBH, c(.05, .5, .95))), "\n")
saveRDS(list(FC = FC, tab = tab, pick = pk, boot = BO, TM = TM, cv = cv), "out/crown_base_34.rds"); cat("done\n")
